import React, { Component } from 'react';
import axios from 'axios';
import MyContext from '../contexts/MyContext';
import '../css/CategoryComponent.css';

class Category extends Component {
  static contextType = MyContext;

  constructor(props) {
    super(props);
    this.state = {
      categories: [],
      txtID: '',
      txtName: '',
      txtSortOrder: 0,
      txtDescription: '',
      cmbStatus: 'Active',
      isEdit: false
    };
  }

  componentDidMount() {
    this.apiGetCategories();
  }

  apiGetCategories = () => {
    const config = { headers: { 'x-access-token': this.context.token } };
    axios.get('/api/admin/categories', config).then((res) => {
      this.setState({ categories: res.data });
    });
  };

  selectItem = (item) => {
    this.setState({
      txtID: item._id,
      txtName: item.name,
      txtSortOrder: item.sortOrder || 0,
      txtDescription: item.description || '',
      cmbStatus: item.status || 'Active',
      isEdit: true
    });
  };

  resetForm = () => {
    this.setState({
      txtID: '',
      txtName: '',
      txtSortOrder: 0,
      txtDescription: '',
      cmbStatus: 'Active',
      isEdit: false
    });
  };

  btnSaveClick = (e) => {
    e.preventDefault();
    const { txtID, txtName, txtSortOrder, txtDescription, cmbStatus, isEdit } = this.state;
    if (!txtName) {
      alert('Vui lòng nhập tên danh mục!');
      return;
    }

    const category = { 
      name: txtName, 
      sortOrder: parseInt(txtSortOrder || 0), 
      description: txtDescription,
      status: cmbStatus 
    };
    const config = { headers: { 'x-access-token': this.context.token } };

    if (isEdit) {
      axios.put(`/api/admin/categories/${txtID}`, category, config).then((res) => {
        if (res.data) {
          alert('Cập nhật danh mục thành công!');
          this.apiGetCategories();
          this.resetForm();
        }
      });
    } else {
      axios.post('/api/admin/categories', category, config).then((res) => {
        if (res.data) {
          alert('Thêm danh mục mới thành công!');
          this.apiGetCategories();
          this.resetForm();
        }
      });
    }
  };

  btnDeleteClick = (id) => {
    if (window.confirm('Bạn có chắc muốn xóa danh mục này?')) {
      const config = { headers: { 'x-access-token': this.context.token } };
      axios.delete(`/api/admin/categories/${id}`, config).then((res) => {
        if (res.data.success) {
          alert('Đã xóa thành công!');
          this.apiGetCategories();
          this.resetForm();
        }
      });
    }
  };

  render() {
    const { categories, txtName, txtSortOrder, txtDescription, cmbStatus, isEdit } = this.state;

    return (
      <div className="category-container">
        <h3 className="category-title">QUẢN LÝ DANH MỤC THỰC ĐƠN</h3>
        <div className="category-layout">
          
          {/* Cột trái: Form thêm/sửa danh mục */}
          <div className="category-form-card">
            <h4 style={{ marginBottom: '20px', color: '#4A2E2B' }}>
              {isEdit ? 'Chỉnh sửa danh mục' : 'Thêm Danh Mục Mới'}
            </h4>
            <form>
              <div className="form-group">
                <label className="form-label">Tên Danh Mục *</label>
                <input
                  type="text"
                  className="form-input"
                  value={txtName}
                  onChange={(e) => this.setState({ txtName: e.target.value })}
                  placeholder="Ví dụ: Lẩu & Nướng..."
                />
              </div>

              <div className="form-group">
                <label className="form-label">Thứ Tự Hiển Thị</label>
                <input
                  type="number"
                  className="form-input"
                  value={txtSortOrder}
                  onChange={(e) => this.setState({ txtSortOrder: e.target.value })}
                />
              </div>

              <div className="form-group">
                <label className="form-label">Mô Tả Danh Mục</label>
                <textarea
                  className="form-textarea"
                  value={txtDescription}
                  onChange={(e) => this.setState({ txtDescription: e.target.value })}
                  placeholder="Mô tả ngắn gọn về nhóm món ăn..."
                />
              </div>

              <div className="form-group">
                <label className="form-label">Trạng Thái</label>
                <select
                  className="form-select"
                  value={cmbStatus}
                  onChange={(e) => this.setState({ cmbStatus: e.target.value })}
                >
                  <option value="Active">Đang hiển thị</option>
                  <option value="Inactive">Tạm ẩn</option>
                </select>
              </div>

              <div style={{ display: 'flex', gap: '10px', marginTop: '20px' }}>
                <button type="submit" onClick={this.btnSaveClick} className="btn-submit">
                  {isEdit ? 'CẬP NHẬT' : 'Lưu Danh Mục'}
                </button>
                {isEdit && (
                  <button type="button" onClick={this.resetForm} className="btn-cancel">
                    HỦY
                  </button>
                )}
              </div>
            </form>
          </div>

          {/* Cột phải: Bảng danh sách danh mục */}
          <div className="category-table-card">
            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '15px' }}>
              <h4 style={{ margin: 0, color: '#4A2E2B' }}>Danh Sách Danh Mục Hiện Có</h4>
              <span style={{ fontSize: '13px', color: '#666' }}>Tổng cộng: {categories.length} Danh mục</span>
            </div>

            <table className="category-table">
              <thead>
                <tr>
                  <th>Thứ tự</th>
                  <th>Tên Danh Mục</th>
                  <th>Số Món</th>
                  <th>Trạng Thái</th>
                  <th>Hành Động</th>
                </tr>
              </thead>
              <tbody>
                {categories.map((item, index) => (
                  <tr key={item._id}>
                    <td style={{ fontWeight: 'bold' }}>{item.sortOrder || (index + 1)}</td>
                    <td style={{ fontWeight: '600' }}>{item.name}</td>
                    <td>{item.productCount || 0} món</td>
                    <td>
                      <span className={item.status === 'Active' ? 'badge-active' : 'badge-inactive'}>
                        {item.status === 'Active' ? 'Đang hiển thị' : 'Tạm ẩn'}
                      </span>
                    </td>
                    <td>
                      <button onClick={() => this.selectItem(item)} className="btn-edit">
                        Sửa
                      </button>
                      <button onClick={() => this.btnDeleteClick(item._id)} className="btn-delete">
                        Xoá
                      </button>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>

        </div>
      </div>
    );
  }
}

export default Category;
